namespace c975L\UiBundle\Tests\Templates;

use PHPUnit\Framework\TestCase;
use Symfony\Component\Finder\Finder;

// An editor's text goes through |sanitize_html('c975l.rich'): a new |raw in these templates has to say here why it is not one
class RawFilterAllowlistTest extends TestCase
{
    // Template => the values printed raw in it, each generated by the server or deliberately markup a sanitizer would break
    private const array ALLOWED = [
        // Translations carrying their own markup, and config values given to them
        'management/form_crud_index.html.twig' => ['trans'],
        'management/email_template_crud_index.html.twig' => ['trans'],
        'management/user_crud_index.html.twig' => ['trans'],
        'components/Form/_submit.html.twig' => ['trans'],
        // Flashes: translations and messages written by controllers
        'layout.html.twig' => ['message'],
        // The bundle's own model text, on a back-office screen
        'management/legal_model_customize.html.twig' => ['drifted[unit.id].html'],
        // Emails: wrappers of rendered children, values escaped by EmailTemplateRenderer, and the html an admin composes on purpose
        'emails/blocks/slot.html.twig' => ['slot'],
        'emails/blocks/text.html.twig' => ['content'],
        'emails/blocks/html.html.twig' => ['content'],
        'emails/blocks/_wrapper.html.twig' => ['block'],
        // Twig's own output, captured by a {% set %} or rendered by the entries' own templates
        'components/Slider/Slider.html.twig' => ['mediaTag', 'zoomedMedia', 'img'],
        'components/Collection/Grid.html.twig' => ['html'],
        'blocks/CollectionEntry.html.twig' => ['entry'],
        // JSON-LD, encoded by JsonLdBuilder with JSON_HEX_TAG
        'components/Contact/Details.html.twig' => ['snippet'],
    ];

    public function testNoRawFilterOutsideTheListedValues(): void
    {
        $found = [];
        foreach ([\dirname(__DIR__, 2) . '/templates', \dirname(__DIR__, 3) . '/ConfigBundle/templates'] as $directory) {
            foreach (new Finder()->files()->in($directory)->name('*.twig') as $file) {
                if (preg_match_all('/\{\{\s*([^{}]*?)\s*\|\s*raw\b/', $file->getContents(), $matches)) {
                    $found[$file->getRelativePathname()] = array_unique(array_map(self::valueOf(...), $matches[1]));
                }
            }
        }

        foreach ($found as $template => $values) {
            foreach ($values as $value) {
                $this->assertContains($value, self::ALLOWED[$template] ?? [], sprintf('"%s" prints "%s" raw.', $template, $value));
            }
        }

        $this->assertNotEmpty($found, 'No |raw found at all, the pattern itself is broken.');
    }

    // What is printed, a translation counting as one whatever its key
    private static function valueOf(string $expression): string
    {
        return str_contains($expression, '|trans') || str_contains($expression, 'trans(') ? 'trans' : trim($expression);
    }
}
